  "guardrail_code": "import json

def enforce_policy(session_log: list[dict], proposed_call: dict) -> dict:
    # Deployment manifest boundaries (hard-coded per deployment)
    SERVERS = {
        "openapi-proxy-mcp": {
            "trust_level": "untrusted_external",
            "uri": "mcp://openapi-proxy-mcp"
        },
        "k8s-mcp": {
            "trust_level": "privileged_infra",
            "uri": "mcp://k8s-mcp",
            "typed_arguments": {
                "delete_pod": {
                    "namespace": {
                        "type": "string",
                        "enum": ["staging", "dev-sandbox"]
                    },
                    "pod_name": {
                        "type": "string",
                        "prefixes": ["worker-", "test-"]
                    }
                }
            }
        }
    }

    server_name = proposed_call.get("server")
    tool_name = proposed_call.get("tool")
    args = proposed_call.get("args", {})
    jwt_aud = proposed_call.get("jwt_aud")
    tenant_id = proposed_call.get("tenant_id")

    server_info = SERVERS.get(server_name)
    if not server_info:
        return {"allow": False, "reason": f"Unknown server: {server_name}"}

    # Clause 0: Token audience
    expected_aud = server_info["uri"]
    if jwt_aud != expected_aud:
        return {"allow": False, "reason": f"jwt_aud mismatch: expected {expected_aud}, got {jwt_aud}"}

    # Clause 7: Declared argument types
    typed_args = server_info.get("typed_arguments", {}).get(tool_name, {})
    for arg_name, constraints in typed_args.items():
        if arg_name not in args:
            continue
        value = args[arg_name]
        # type check
        expected_type = constraints.get("type")
        if expected_type == "string" and not isinstance(value, str):
            return {"allow": False, "reason": f"Argument {arg_name} must be a string, got {type(value).__name__}"}
        # enum check
        enum_vals = constraints.get("enum")
        if enum_vals is not None:
            if not isinstance(value, str) or value not in enum_vals:
                return {"allow": False, "reason": f"Argument {arg_name} value '{value}' not in allowed enum {enum_vals}"}
        # prefixes check
        prefixes = constraints.get("prefixes")
        if prefixes is not None:
            if not isinstance(value, str) or not any(value.startswith(p) for p in prefixes):
                return {"allow": False, "reason": f"Argument {arg_name} value '{value}' does not start with allowed prefixes {prefixes}"}

    # Clause 1: Exfiltration to less-trusted server
    trust_level = server_info.get("trust_level")
    if trust_level in ("untrusted_third_party", "untrusted_external"):
        # Check args for postgres URIs
        def contains_postgres_uri(obj):
            if isinstance(obj, str):
                if obj.startswith("postgres://") or obj.startswith("postgresql://"):
                    return True
            elif isinstance(obj, dict):
                for v in obj.values():
                    if contains_postgres_uri(v):
                        return True
            elif isinstance(obj, list):
                for item in obj:
                    if contains_postgres_uri(item):
                        return True
            return False
        if contains_postgres_uri(args):
            return {"allow": False, "reason": "Postgres connection URI found in args to untrusted server"}
        # Check for qualifying strings from privileged server outputs
        privileged_levels = {"privileged_internal", "privileged_cloud", "privileged_secrets", "privileged_financial", "privileged_local"}
        def extract_qualifying_strings(obj):
            strings = []
            if isinstance(obj, str) and len(obj) >= 4:
                strings.append(obj)
            elif isinstance(obj, dict):
                for v in obj.values():
                    strings.extend(extract_qualifying_strings(v))
            elif isinstance(obj, list):
                for item in obj:
                    strings.extend(extract_qualifying_strings(item))
            return strings
        privileged_strings = set()
        for entry in session_log:
            entry_server = entry.get("server")
            entry_info = SERVERS.get(entry_server)
            if entry_info and entry_info.get("trust_level") in privileged_levels:
                output = entry.get("output")
                if output:
                    privileged_strings.update(extract_qualifying_strings(output))
        def contains_privileged_string(obj):
            if isinstance(obj, str) and len(obj) >= 4 and obj in privileged_strings:
                return True
            elif isinstance(obj, dict):
                for v in obj.values():
                    if contains_privileged_string(v):
                        return True
            elif isinstance(obj, list):
                for item in obj:
                    if contains_privileged_string(item):
                        return True
            return False
        if contains_privileged_string(args):
            return {"allow": False, "reason": "Qualifying string from privileged server output found in args to untrusted server"}

    # Clause 2: Unapproved schema change
    approved_domain = server_info.get("approved_domain")
    if approved_domain:
        for key, val in args.items():
            if key == "webhook_url" or key.endswith("_url"):
                if not isinstance(val, str) or not val.startswith(approved_domain):
                    return {"allow": False, "reason": f"URL {key} does not start with approved_domain {approved_domain}"}
                # Check for tools/list_changed without reapproval
                list_changed_seen = False
                for entry in session_log:
                    if entry.get("type") == "notifications/tools/list_changed" and entry.get("server") == server_name:
                        list_changed_seen = True
                    elif entry.get("type") == "admin/reapprove_schema" and entry.get("server") == server_name:
                        list_changed_seen = False
                if list_changed_seen:
                    return {"allow": False, "reason": f"Schema changed for {server_name} without reapproval"}

    # Clause 3: Untrusted fragments in role ARN
    if server_name == "aws-iam-mcp" and tool_name == "assume_role":
        role_arn = args.get("role_arn")
        allowed_arn_prefix = server_info.get("allowed_arn_prefix")
        if not isinstance(role_arn, str) or not role_arn.startswith(allowed_arn_prefix):
            return {"allow": False, "reason": f"role_arn must start with {allowed_arn_prefix}"}
        # Check for qualifying strings from untrusted_external outputs
        untrusted_strings = set()
        for entry in session_log:
            entry_server = entry.get("server")
            entry_info = SERVERS.get(entry_server)
            if entry_info and entry_info.get("trust_level") == "untrusted_external":
                output = entry.get("output")
                if output:
                    untrusted_strings.update(extract_qualifying_strings(output))
        if isinstance(role_arn, str) and any(s in role_arn for s in untrusted_strings if len(s) >= 4):
            return {"allow": False, "reason": "role_arn contains qualifying string from untrusted_external server output"}

    # Clause 4: Secret path scope
    if server_name == "vault-mcp" and tool_name == "read_secret":
        secret_path = args.get("secret_path")
        allowed_prefixes = server_info.get("allowed_secret_prefixes", [])
        if not isinstance(secret_path, str) or not any(secret_path.startswith(p) for p in allowed_prefixes):
            return {"allow": False, "reason": f"secret_path must start with one of {allowed_prefixes}"}

    # Clause 5: Canonical path boundary
    if server_name == "filesystem-mcp" and tool_name in ("read_file", "write_file"):
        allowed_root = server_info.get("allowed_root")
        if allowed_root:
            path = args.get("path")
            if not isinstance(path, str) or not path:
                return {"allow": False, "reason": "path must be a non-empty string"}
            # URL percent-decode twice
            import urllib.parse
            decoded = urllib.parse.unquote(urllib.parse.unquote(path))
            # Unicode NFKC normalization
            import unicodedata
            normalized = unicodedata.normalize("NFKC", decoded)
            # POSIX path normalization
            import posixpath
            norm_path = posixpath.normpath(normalized)
            root = allowed_root.rstrip("/")
            if not (norm_path == root or norm_path.startswith(root + "/")):
                return {"allow": False, "reason": f"path {norm_path} escapes allowed_root {root}"}

    # Clause 6: Explicit tenant account
    connection_mode = server_info.get("connection_mode")
    if connection_mode == "shared_persistent_sse":
        account_scoped = server_info.get("account_scoped_tools", [])
        if tool_name in account_scoped:
            account_id = args.get("account_id")
            expected = f"acct_{tenant_id}"
            if not isinstance(account_id, str) or account_id != expected:
                return {"allow": False, "reason": f"account_id must be '{expected}' for this tenant"}

    # Clause 8: Hotfix constraints (github-mcp create_hotfix_branch)
    hotfix_constraints = server_info.get("hotfix_constraints")
    if hotfix_constraints and tool_name == "create_hotfix_branch":
        repo = args.get("repo")
        branch = args.get("branch")
        repo_prefix = hotfix_constraints.get("repo_prefix")
        repo_suffix = hotfix_constraints.get("repo_suffix")
        branch_prefix = hotfix_constraints.get("branch_prefix")
        if not (isinstance(repo, str) and repo.startswith(repo_prefix) and repo.endswith(repo_suffix)):
            return {"allow": False, "reason": f"repo must start with {repo_prefix} and end with {repo_suffix}"}
        if not (isinstance(branch, str) and branch.startswith(branch_prefix)):
            return {"allow": False, "reason": f"branch must start with {branch_prefix}"}

    return {"allow": True, "reason": "Policy checks passed"}
